var wakeLock=null;function initWakeLock(o=!0){navigator.wakeLock?.request("screen").then(e=>{(wakeLock=e).onrelease=()=>{wakeLock=null,showToast("","Screen lock deactivated.","alert-warning")},o&&showToast("","Screen lock activated.","alert-info")}).catch(e=>{showToast("","Failed to toggle screen lock.","alert-error"),console.log(`Screen lock error: ${e.name}, `+e.message)})}initWakeLock(!1);